// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        // No precondition needed; the rule involves only the public state after Collect
        // Call Collect with arbitrary am; the function may revert, but we still check MinSum
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));
        success; // use to avoid unused variable warning
        assertTrue(c.MinSum() == 1 ether);
    }
}

